#' Data Generation Functions
#'
#' Functions for generating synthetic data using various methods
#' including multivariate normal, synthpop, parametric, and empirical resampling.

#' Generate synthetic data based on specified method
#'
#' @param n Sample size
#' @param data_generation List with method and parameters
#' @param predictor_config List with predictor specifications
#' @param reference_model Character string specifying reference model
#' @param seed Random seed
#' @return Data frame with generated data
#' @noRd
generate_data <- function(n, data_generation, predictor_config, reference_model, seed) {
  if (!is.null(seed)) set.seed(seed)
  method <- data_generation$method
  params <- data_generation$params

  if (method == "joint_mvn") {
    data <- generate_mvn_data(n, params, predictor_config, reference_model)

  } else if (method == "synthetic") {
    if (!requireNamespace("synthpop", quietly = TRUE)) {
      stop("synthpop package required for synthetic data generation")
    }
    data <- generate_synthetic_data(n, params, predictor_config, reference_model)

  } else if (method == "parametric") {
    data <- generate_parametric_data(n, params, predictor_config, reference_model)

  } else if (method == "empirical") {
    data <- resample_empirical_data(n, params$empirical_data, predictor_config, reference_model)

  } else {
    stop("Unknown data generation method: ", method)
  }

  required_columns <- c("y", predictor_config$names)
  if (!all(required_columns %in% names(data))) {
    stop("Generated/resampled data must contain y and all configured predictors")
  }
  group_ids <- attr(data$y, "group_ids")
  if (!is.null(group_ids)) {
    data$.group <- factor(group_ids)
    attr(data$y, "group_ids") <- NULL
  }
  return(data)
}

#' Generate data from multivariate normal distribution
#'
#' @param n Sample size
#' @param params List with correlation/covariance matrix and mean vector
#'   - correlation_matrix or covariance_matrix: the covariance structure
#'   - joint_outcome: if TRUE, treats first row/col as outcome Y (generates Y jointly with X)
#'   - sd_vector: standard deviations for each variable (optional)
#'   - mean_vector: means for each variable (optional)
#' @param predictor_config List with predictor specifications
#' @param reference_model Character string specifying reference model
#' @return Data frame with predictors and outcome
#' @noRd
generate_mvn_data <- function(n, params, predictor_config, reference_model) {
  # Prepare covariance matrix
  if (!is.null(params$covariance_matrix)) {
    Sigma <- params$covariance_matrix
  } else if (!is.null(params$correlation_matrix)) {
    if (is.null(params$sd_vector)) {
      params$sd_vector <- rep(1, nrow(params$correlation_matrix))
    }
    D <- diag(params$sd_vector, nrow = length(params$sd_vector))
    Sigma <- D %*% params$correlation_matrix %*% D
  } else {
    stop("Must provide either correlation_matrix or covariance_matrix")
  }

  # Mean vector
  mu <- if (!is.null(params$mean_vector)) params$mean_vector else rep(0, ncol(Sigma))

  # Generate data from multivariate normal
  if (!requireNamespace("MASS", quietly = TRUE)) {
    stop("MASS package required for multivariate normal generation")
  }

  # Check if joint_outcome mode: first column is Y, rest are X
  # This generates Y jointly with X from full covariance structure
  joint_outcome <- params$joint_outcome %||% FALSE

  if (joint_outcome) {
    if (reference_model == "ordinal") {
      stop("joint_outcome = TRUE produces a continuous outcome and cannot use reference_model = 'ordinal'")
    }
    # Joint MVN: first variable is outcome, rest are predictors
    # The covariance matrix should be (1+p) x (1+p) where p = number of predictors
    all_data <- MASS::mvrnorm(n = n, mu = mu, Sigma = Sigma)

    # First column is Y, rest are X
    y <- all_data[, 1]
    X <- all_data[, -1, drop = FALSE]
    colnames(X) <- predictor_config$names

    data <- data.frame(y = y, as.data.frame(X), check.names = FALSE)
  } else {
    # Conditional generation: generate X, then Y = Xβ + ε
    X <- MASS::mvrnorm(n = n, mu = mu, Sigma = Sigma)
    colnames(X) <- predictor_config$names

    # Generate outcome based on reference model
    y <- generate_outcome(X, predictor_config, reference_model)

    data <- data.frame(y = y, as.data.frame(X), check.names = FALSE)
  }

  return(data)
}

#' Generate data using synthpop
#'
#' @param n Sample size
#' @param params List with synthpop parameters
#' @param predictor_config List with predictor specifications
#' @param reference_model Character string specifying reference model
#' @return Data frame with synthetic data
#' @noRd
generate_synthetic_data <- function(n, params, predictor_config, reference_model) {
  if (is.null(params$base_data)) {
    stop("synthpop method requires base_data in params")
  }

  # Use synthpop to generate synthetic data
  syn_obj <- synthpop::syn(
    params$base_data,
    m = 1,
    k = n,
    method = params$method %||% "cart",
    seed = params$seed %||% NULL
  )

  data <- syn_obj$syn
  return(data)
}

#' Generate data parametrically
#'
#' @param n Sample size
#' @param params List with distribution parameters for each predictor
#' @param predictor_config List with predictor specifications (must include 'names' and 'types')
#' @param reference_model Character string specifying reference model
#' @return Data frame with generated data
#' @noRd
generate_parametric_data <- function(n, params, predictor_config, reference_model) {
  # Validate required fields
  if (is.null(predictor_config$types)) {
    stop("predictor_config$types is required for parametric data generation")
  }
  if (length(predictor_config$names) != length(predictor_config$types)) {
    stop("Length of predictor_config$names must match predictor_config$types")
  }

  X <- matrix(NA, nrow = n, ncol = length(predictor_config$names))
  colnames(X) <- predictor_config$names

  # Generate each predictor according to its specification
  for (i in seq_along(predictor_config$names)) {
    var_name <- predictor_config$names[i]
    var_type <- predictor_config$types[i]

    if (var_type == "continuous") {
      # Default to normal distribution
      dist <- params[[var_name]]$distribution %||% "normal"
      if (dist == "normal") {
        mean_val <- params[[var_name]]$mean %||% 0
        sd_val <- params[[var_name]]$sd %||% 1
        X[, i] <- rnorm(n, mean_val, sd_val)
      } else if (dist == "uniform") {
        min_val <- params[[var_name]]$min %||% 0
        max_val <- params[[var_name]]$max %||% 1
        X[, i] <- runif(n, min_val, max_val)
      } else {
        stop("Unsupported continuous distribution: ", dist)
      }
    } else if (var_type == "binary") {
      prob <- params[[var_name]]$prob %||% 0.5
      X[, i] <- rbinom(n, 1, prob)
    } else if (var_type == "categorical") {
      levels <- params[[var_name]]$levels
      if (!is.numeric(levels) || !length(levels) || anyNA(levels)) {
        stop("Parametric categorical levels must be numeric scores; use empirical data for factors")
      }
      probs <- params[[var_name]]$probs %||% rep(1/length(levels), length(levels))
      X[, i] <- sample(levels, n, replace = TRUE, prob = probs)
    } else {
      stop("Unsupported predictor type: ", var_type)
    }
  }

  # Generate outcome
  y <- generate_outcome(X, predictor_config, reference_model)

  data <- data.frame(y = y, as.data.frame(X), check.names = FALSE)
  return(data)
}

#' Resample from empirical data
#'
#' @param n Sample size
#' @param empirical_data Data frame with empirical data
#' @param predictor_config List with predictor specifications
#' @param reference_model Character string specifying reference model
#' @return Data frame with resampled data
#' @noRd
resample_empirical_data <- function(n, empirical_data, predictor_config, reference_model) {
  if (is.null(empirical_data)) {
    stop("empirical method requires empirical_data")
  }

  # Bootstrap resample
  if (!is.data.frame(empirical_data) || nrow(empirical_data) == 0) {
    stop("empirical_data must be a nonempty data frame")
  }
  indices <- sample(seq_len(nrow(empirical_data)), n, replace = TRUE)
  data <- empirical_data[indices, , drop = FALSE]

  # Optionally regenerate outcome based on reference model
  if (!is.null(predictor_config$regenerate_outcome) && predictor_config$regenerate_outcome) {
    X <- as.matrix(data[, predictor_config$names, drop = FALSE])
    data$y <- generate_outcome(X, predictor_config, reference_model)
  }

  return(data)
}

#' Generate outcome variable based on reference model
#'
#' @param X Matrix of predictors
#' @param predictor_config List with predictor specifications and effects
#' @param reference_model Character string specifying model type
#' @return Numeric vector of outcomes
#' @noRd
generate_outcome <- function(X, predictor_config, reference_model) {
  n <- nrow(X)

  # Get effect sizes (fixed or sample from ranges)
  effects <- get_effect_sizes(predictor_config)
  if (length(effects) != ncol(X)) stop("Effects must match the predictor matrix columns")

  # Linear predictor
  eta <- as.matrix(X) %*% matrix(effects, ncol = 1)

  if (reference_model == "lm") {
    # Linear model: y = Xβ + ε
    sigma <- predictor_config$effects$residual_sd %||% 1
    y <- drop(eta) + rnorm(n, 0, sigma)

  } else if (reference_model == "glm") {
    # Generalized linear model
    family_type <- predictor_config$effects$family %||% "binomial"
    if (family_type == "binomial") {
      prob <- plogis(eta)
      y <- rbinom(n, 1, prob)
    } else if (family_type == "poisson") {
      lambda <- exp(eta)
      y <- rpois(n, lambda)
    } else if (family_type == "gamma") {
      shape <- predictor_config$effects$shape %||% 2
      rate <- exp(-eta)
      y <- rgamma(n, shape = shape, rate = rate)
    } else {
      stop("Unsupported generating family: ", family_type)
    }

  } else if (reference_model %in% c("lmm", "glmm")) {
    # Mixed models - add random effects
    n_groups <- predictor_config$effects$n_groups %||% 10
    group_var <- predictor_config$effects$group_variance %||% 0.5

    group_id <- sample(1:n_groups, n, replace = TRUE)
    random_effects <- rnorm(n_groups, 0, sqrt(group_var))[group_id]

    if (reference_model == "lmm") {
      sigma <- predictor_config$effects$residual_sd %||% 1
      y <- drop(eta) + random_effects + rnorm(n, 0, sigma)
    } else {
      prob <- plogis(eta + random_effects)
      y <- rbinom(n, 1, prob)
    }
    attr(y, "group_ids") <- group_id
  } else if (reference_model == "ordinal") {
    # Latent-variable proportional-odds data generation. Thresholds define
    # increasing response categories and can be customized in predictor_config.
    thresholds <- predictor_config$effects$thresholds %||% c(-0.5, 0.5)
    if (!is.numeric(thresholds) || length(thresholds) < 2 ||
        is.unsorted(thresholds, strictly = TRUE)) {
      stop("ordinal effects$thresholds must contain at least two increasing values")
    }
    labels <- predictor_config$effects$labels %||%
      as.character(seq_len(length(thresholds) + 1))
    if (length(labels) != length(thresholds) + 1) {
      stop("ordinal effects$labels must have length thresholds + 1")
    }

    latent_y <- drop(eta) + stats::rlogis(n)
    y <- cut(
      latent_y,
      breaks = c(-Inf, thresholds, Inf),
      labels = labels,
      ordered_result = TRUE
    )
  } else {
    stop("Unknown reference model: ", reference_model)
  }

  return(y)
}

#' Get effect sizes (either fixed or sampled from ranges)
#'
#' @param predictor_config List with effects specifications
#' @return Numeric vector of effect sizes
#' @noRd
get_effect_sizes <- function(predictor_config) {
  if (!is.null(predictor_config$effects$fixed)) {
    effects <- predictor_config$effects$fixed
  } else if (!is.null(predictor_config$effects$ranges)) {
    # Sample from ranges
    ranges <- predictor_config$effects$ranges
    effects <- sapply(ranges, function(r) runif(1, min(r), max(r)))
  } else {
    stop("Must provide either fixed effects or ranges in predictor_config$effects")
  }
  if (!is.null(names(effects)) && !is.null(predictor_config$names)) {
    effects <- effects[predictor_config$names]
  }
  if (!is.numeric(effects) || !length(effects) ||
      (!is.null(predictor_config$names) && length(effects) != length(predictor_config$names)) ||
      anyNA(effects) || any(!is.finite(effects))) {
    stop("Effects must supply one finite numeric coefficient per predictor")
  }
  unname(effects)
}
